#!/usr/bin/env python3
"""Underline all headlines (all-caps section titles) in quarterly_report.docx.

Operates on the unpacked intermediate state at unpacked_quarterly_report/.
A headline paragraph is one whose text is non-empty, contains at least one
letter, and is entirely uppercase (e.g. "EXECUTIVE SUMMARY", "Q1 2025 OUTLOOK").
Underlining is applied at the run level via <w:u w:val="single"/> in w:rPr.
"""
import os
import sys

BASE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(BASE, ".codex", "skills", "docx"))

from scripts.utilities import XMLEditor

doc_xml = os.path.join(BASE, "unpacked_quarterly_report", "word", "document.xml")
editor = XMLEditor(doc_xml)
dom = editor.dom


def paragraph_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        for child in t.childNodes:
            if child.nodeType == child.TEXT_NODE:
                parts.append(child.data)
    return "".join(parts)


def is_headline(p):
    text = paragraph_text(p).strip()
    if not text:
        return False
    if not any(c.isalpha() for c in text):
        return False
    return text == text.upper()


def direct_children(elem, tag):
    return [
        c
        for c in elem.childNodes
        if c.nodeType == c.ELEMENT_NODE and c.tagName == tag
    ]


headlines = []
count = 0
for p in dom.getElementsByTagName("w:p"):
    if not is_headline(p):
        continue
    headlines.append(paragraph_text(p).strip())
    for run in direct_children(p, "w:r"):
        # Only runs that carry visible text need underlining
        if not run.getElementsByTagName("w:t"):
            continue
        rPrs = direct_children(run, "w:rPr")
        if rPrs:
            rPr = rPrs[0]
        else:
            rPr = dom.createElement("w:rPr")
            first_elem = None
            for c in run.childNodes:
                if c.nodeType == c.ELEMENT_NODE:
                    first_elem = c
                    break
            if first_elem is not None:
                run.insertBefore(rPr, first_elem)
            else:
                run.appendChild(rPr)
        us = [
            c
            for c in rPr.childNodes
            if c.nodeType == c.ELEMENT_NODE and c.tagName == "w:u"
        ]
        if us:
            us[0].setAttribute("w:val", "single")
        else:
            u = dom.createElement("w:u")
            u.setAttribute("w:val", "single")
            rPr.appendChild(u)
    count += 1

editor.save()
print(f"Underlined {count} headlines:")
for h in headlines:
    print("  - " + h)

#!/usr/bin/env python3
"""
Task helper: underline all headlines in the unpacked quarterly_report.docx
intermediate state (unpacked_quarterly_report/word/document.xml).

Headlines are identified by the known all-caps section titles of the report
plus the general rule: a paragraph whose text contains letters and equals its
own uppercase form. The <w:u w:val="single"/> run property is added to every
run of each headline paragraph (run properties are created if missing, and
duplicate underline properties are avoided).
"""
import sys

try:
    from defusedxml import minidom
except ImportError:  # pragma: no cover - stdlib fallback
    from xml.dom import minidom

XML_PATH = "unpacked_quarterly_report/word/document.xml"

# Explicitly known section headlines in the report (from the document.xml body).
HEADLINES = {
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
}


def para_text(p):
    """Concatenate the text inside a paragraph (pPr contains no text)."""
    parts = []
    for node in p.childNodes:
        if node.nodeType == node.TEXT_NODE:
            parts.append(node.data)
        elif node.nodeType == node.ELEMENT_NODE and node.nodeName != "w:pPr":
            parts.append(para_text(node))
    return "".join(parts)


def underline_run(dom, run):
    """Add <w:u w:val='single'/> to a run's run properties."""
    rpr = None
    for child in run.childNodes:
        if getattr(child, "nodeName", None) == "w:rPr":
            rpr = child
            break
    if rpr is None:
        rpr = dom.createElement("w:rPr")
        if run.firstChild:
            run.insertBefore(rpr, run.firstChild)
        else:
            run.appendChild(rpr)
    for child in rpr.childNodes:
        if getattr(child, "nodeName", None) == "w:u":
            child.setAttribute("w:val", "single")
            return
    u = dom.createElement("w:u")
    u.setAttribute("w:val", "single")
    rpr.appendChild(u)


def main():
    dom = minidom.parse(XML_PATH)
    matched = []
    for p in dom.getElementsByTagName("w:p"):
        txt = " ".join(para_text(p).split())
        looks_like_headline = txt in HEADLINES or (
            txt
            and any(ch.isalpha() for ch in txt)
            and txt == txt.upper()
        )
        if not looks_like_headline:
            continue
        for run in p.getElementsByTagName("w:r"):
            underline_run(dom, run)
        matched.append(txt)

    if not matched:
        print("ERROR: no headlines found; document left unchanged")
        sys.exit(1)

    with open(XML_PATH, "wb") as fh:
        fh.write(dom.toxml(encoding="ascii"))
    print("Underlined %d headline paragraph(s):" % len(matched))
    for t in matched:
        print(" - " + t)
    print("Done.")


if __name__ == "__main__":
    main()

